selected.compute:
options = read('/input/options')
ids = []
for record in options:
    ids = ids + [record['id']]
result = []
for size in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(ids, size):
        candidate_ids = list(group)
        if valid(candidate_ids):
            result = candidate_ids
            break
    if len(result) > 0:
        break
if len(result) > 0:
    result_records = []
    for option_id in result:
        for record in options:
            if record['id'] == option_id:
                result_records = result_records + [record]
    result_records = sorted(result_records, key=lambda record: [record[field] for field in goal['order_by']])
    result = [record['id'] for record in result_records]

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if valid(selection):
        result = selection
    else:
        result = []
if len(result) > 0 and not exists('/output/selection'):
    write('/output/selection', result)
if len(result) > 0:
    delivery = receipt('report')
    if delivery == 'unattempted':
        send('report', 'team', result)
    elif delivery == 'unknown':
        status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')
